else:
	return True

# === INPUT: lista de instancias (como la que envías en el ejemplo) ===
instances = value # o payload, o como lo estés recibiendo

# === 1️⃣ Extraer unidades únicas ===
units = sorted(list(set([i.get('unit', 'default') for i in instances])))

# === 2️⃣ Crear plots dinámicos ===
plots = []
for _ in units:
	plots.append({
		"relativeWeight": 3,
		"color": "var(--neutral-10)",
		"markers": [],
		"style": {"classes": ""}
	})

# === 3️⃣ Crear axes dinámicos ===
axes = []
for idx, unit in enumerate(units):
	axis = {
		"name": unit,
		"position": "left",
		"width": 60,
		"color": "#757A7F",
		"dataFormat": "0,0.##",
		"range": {"auto": True, "min": "", "max": ""},
		"label": {
			"text": unit.capitalize(),
			"offset": 0,
			"font": {"color": "#757A7F", "size": 12},
			"style": {"classes": ""}
		},
		"tick": {
			"color": "#757A7F",
			"count": "Auto",
			"label": {
				"format": "Auto",
				"font": {"color": "#757A7F", "size": 10},
				"style": {"classes": ""}
			},
			"style": {"classes": ""}
		},
		"style": {"classes": ""}
	}

	# === 4️⃣ A partir del 3er eje, agregar el binding "translate" ===
	if idx >= 2:
		axis["label"]["style"]["translate"] = {
			"type": "property",
			"config": {"path": "this.custom.count"},
			"transforms": [
				{
					"type": "expression",
					"expression": (
						"if({value}=1, '-8px 44%', "
						"if({value}=2, '-8px 22%', "
						"if({value}=3, '-8px 13%', '-8px 10%')))"
					)
				}
			]
		}

	axes.append(axis)

# === 5️⃣ Guardar los resultados ===
self.props.plots = plots
self.props.axes = axes

# === 6️⃣ Crear pens dinámicos ===
pens = []

for inst in instances:
	unit = inst.get("unit", "default")
	color = inst.get("color", "#00bcd4")  # color por defecto si no viene
	pathSource = inst.get("pathSource", "")
	name = inst.get("name", "Unnamed Pen")

	# Buscar el índice del plot correspondiente a la unidad
	plotIndex = units.index(unit) if unit in units else 0

	pen = {
		"name": name,
		"visible": True,
		"enabled": True,
		"selectable": False,
		"axis": unit,
		"plot": plotIndex,
		"display": {
			"type": "line",
			"interpolation": "curveLinear",
			"breakLine": True,
			"radius": 3,
			"styles": {
				"normal": {
					"stroke": {"color": color, "width": 1, "opacity": 0.8, "dashArray": 0},
					"fill": {"color": color, "opacity": 0.8},
				},
				"highlighted": {
					"stroke": {"color": color, "width": 1, "opacity": 1, "dashArray": 0},
					"fill": {"color": color, "opacity": 1},
				},
				"selected": {
					"stroke": {"color": color, "width": 1, "opacity": 1, "dashArray": 0},
					"fill": {"color": color, "opacity": 1},
				},
				"muted": {
					"stroke": {"color": color, "width": 1, "opacity": 0.4, "dashArray": 0},
					"fill": {"color": color, "opacity": 0.4},
				},
			},
		},
		"data": {
			"source": pathSource,
			"aggregateMode": "default",
		},
	}

	pens.append(pen)

# === 7️⃣ Asignar al gráfico ===
return pens

